INSERT INTO guides (id, title, content, category, tone, status, created_at) VALUES
('guide-001','婴童直播间 · 小珍珠kids','老板爽快、包邮、价格实在，婴童服饰首选蹲播。','婴童好物（0-3岁）','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-002','1688 同源工厂','① 温州鱼校长（奇诺鼠工厂店），与抖音官方店同款同线、可放心冲；② 织里幼禾（蔓葡代工），款式质量靠谱。买前可先在抖音官方店和1688对比一件。','婴童好物（0-3岁）','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-003','鞋卡（品牌大促拼卡）','基诺浦、江博士、泰兰尼斯常有 800元/6双 鞋卡，闲鱼可收单张，一般 165 元、好价 150 元；注意甄别真伪。','婴童好物（0-3岁）','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-004','拼单群（先款后货，有风险）','小红书可搜到大量拼单群，通常吊牌价 2-4 折、同款线下约 8 折；但先款后货、等待可能超两个月，存在群主跑路风险，务必甄别。','婴童好物（0-3岁）','warn','approved','2026-10-22T00:00:00.000Z'),
('guide-005','小荷包分账户攒钱','用零钱通/小荷包分开记日常开销、朋友出行费用、攒钱目标，闲钱存零钱通有收益，积少成多；自己的钱存银行吃利息，日常零钱放零钱通随取随用。','日常攒钱与记账','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-006','源头自采 + 自带饭菜','常回老家带自家种的菜、自家榨的油、跑山猪肉，线上买菜一次七十多，自带+自采能省出水电费；上班自己带饭、晚饭回家做，一天外卖60元变做饭20元，一个月省千余元。','日常攒钱与记账','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-007','网购生鲜比价 + 先领券','别只在美团直接结账，多平台比价、先领券再下单，避开囤货浪费；拼多多可提前拼单买耐放的菜。','日常攒钱与记账','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-008','出行比价（携程低价日历）','订酒店车票用携程低价日历避开高峰，同一酒店多平台价格不一，对比一下能省一百多。','日常攒钱与记账','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-009','闲鱼会员 / 二手妙用','会员用不长就开短期会员同样享受权益；闲鱼可收二手、代下单、收鞋卡，是省钱利器。','日常攒钱与记账','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-010','小蚕 App','外卖+团购返现，分外卖、到店两部分，不同返现比例与额度，常点外卖必备。','App 省钱工具','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-011','拼多多省钱法','先搜商品收藏，再从底部活动页进，遵循「先敲蛋→再夺宝→最后返现」原则；实测149元平底锅114元到手。','App 省钱工具','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-012','抖省省 App','抖音团购返现工具，比抖音直播间更省。','App 省钱工具','normal','approved','2026-10-22T00:00:00.000Z'),
('guide-013','代下单（麦当劳/KFC/必胜客）','淘宝搜「麦当劳代下单」等，可代下单省钱；另有大众点评橙V探店、移动网龄生日月领电影券等技巧。','App 省钱工具','normal','approved','2026-10-22T00:00:00.000Z');
INSERT INTO activities (id, title, category, type, hot, description, source, deadline, verify, score, conditions, doubts, link, value, entry, status, created_at) VALUES
('act-001','阿里云 ECS 云服务器免费试用（个人300元/企业660元）','技术资源','quota',1,'个人认证享 300 元免费额度，企业 660 元，3 个月内灵活体验；最高可试 4核8G（企业 8核16G），每月 20GB 内地+200GB 境外流量。','阿里云官方（free.aliyun.com）','长期（额度3个月有效）','verified',95,'["完成实名认证","须为产品新用户","额度3个月内消耗"]','["试用ECS不支持备案"]','https://free.aliyun.com','¥300/¥660 额度','阿里云 → free.aliyun.com','approved','2026-10-22T00:00:00.000Z'),
('act-002','阿里云 学生机 免费1年 ECS','技术资源','quota',1,'国内在校大学生学信网认证通过，发 300 元无门槛代金券，可 0 元购 2核2G、40G 云盘 ECS，最长免费 1 年。','阿里云高校计划（官方）','长期（视活动）','verified',90,'["仅限在校大学生","需学信网学籍校验","未参加过历史学生活动"]','["毕业后失效"]','https://www.aliyun.com','1年免费','阿里云 → 高校计划 → 学生认证','approved','2026-10-22T00:00:00.000Z'),
('act-003','阿里云 云数据库 RDS MySQL 免费试用','技术资源','quota',1,'RDS MySQL Serverless 版 3 个月内免费（0.5-2RCU，50GB），全托管、自动备份，适合新项目原型。','阿里云免费试用中心（官方）','3个月','verified',88,'["完成实名认证","数据库产品新用户"]','["到期转为付费"]','https://free.aliyun.com','3个月免费','阿里云 → 免费试用 → 云数据库 RDS','approved','2026-10-22T00:00:00.000Z'),
('act-004','阿里云 PolarDB-X Zero 免费分布式数据库','技术资源','quota',1,'无需登录付费、API 秒建实例的 MySQL 兼容分布式数据库，标准版 2核4G，默认1天、最长30天，适合 AI Agent 记忆存储与原型验证。','阿里云官方（PolarDB-X Zero）','最长30天/实例','verified',90,'["通过 HTTP API 创建","同一IP限2个实例","5次/分钟"]','["到期自动回收，需提前导出"]','https://www.aliyun.com','完全免费','PolarDB-X Zero 官网','approved','2026-10-22T00:00:00.000Z'),
('act-005','阿里云 云数据库 Redis 免费试用','技术资源','quota',0,'Redis 社区版 2G 免费试用 3 个月，支持高可用、备份恢复、弹性伸缩。','阿里云免费试用中心（官方）','3个月','verified',82,'["完成实名认证","Redis 产品新用户"]','["到期转付费"]','https://free.aliyun.com','3个月免费','阿里云 → 免费试用 → Redis','approved','2026-10-22T00:00:00.000Z'),
('act-006','阿里云 对象存储 OSS / 对象存储免费额度','技术资源','quota',0,'新用户可领 OSS 免费额度（含存储/流量/请求次数），适合图床、静态资源托管。具体以试用中心卡片为准。','阿里云免费试用中心（官方）','视产品（1-3个月）','verified',78,'["完成实名认证","OSS 产品新用户"]','["额度耗尽即计费"]','https://free.aliyun.com','免费额度','阿里云 → 免费试用 → 对象存储 OSS','approved','2026-10-22T00:00:00.000Z'),
('act-007','阿里云百炼 千问 AI 平台 1亿+ tokens','技术资源','quota',0,'千问 AI 平台新用户赠送 1 亿+ tokens 额度，含 Qwen3.8-Max/Flash 等旗舰模型体验；百炼另有 30+ 款模型免费体验。','阿里云百炼（官方）','长期（额度有效）','verified',80,'["完成实名认证","新用户赠送"]','["额度耗尽后计费"]','https://bailian.aliyun.com','1亿+ tokens','阿里云 → 百炼平台','approved','2026-10-22T00:00:00.000Z'),
('act-008','GitHub Student Developer Pack 学生开发者包','技术资源','quota',1,'在校生用官方学生邮箱认证后，可领 GitHub 学生包：含多家云厂商赠金、域名、IDE、AI 工具等多项权益。','GitHub Education（官方）','长期（需每学期续期）','verified',85,'["需学生邮箱/.edu 认证","每年续认证"]','["国内访问部分服务不稳定"]','https://education.github.com/pack','多项免费权益','GitHub Education → Student Pack','approved','2026-10-22T00:00:00.000Z'),
('act-009','中国移动 和包APP 充话费随机立减0.01-20元','话费充值','cash',1,'充 20 元及以上随机立减 0.01-20 元，总量 150 万份、每日 12 万份，先到先得，被充号码须为移动号。','中移金融/和包（官方）','至 2026-10-31','verified',80,'["充20元及以上","移动号码","先到先得"]','["随机立减非固定"]','#','随机最高¥20','和包 APP → 话费充值','approved','2026-10-22T00:00:00.000Z'),
('act-010','中国移动 周三充值日 抢88折/12-13元立减券','话费充值','cash',1,'每周三 8:00，中国移动 APP 抢 88 折券或 12-13 元立减券；另有签到领 0.5-2 元话费券。','中国移动 APP（官方）','每周三','verified',78,'["每周三 8:00","移动号码"]','["券数量有限"]','#','88折券','中国移动 APP → 周三充值日','approved','2026-10-22T00:00:00.000Z'),
('act-011','中国联通 APP 官方充值折扣（充100约96.5元）','话费充值','cash',0,'联通 APP 官方充值常驻折扣：充50约48.25、充100约96.5、充200约193，充得越多越省。','中国联通 APP（官方）','长期','verified',72,'["联通号码"]','["折扣因活动微调"]','#','约96.5折','中国联通 APP → 交费充值','approved','2026-10-22T00:00:00.000Z'),
('act-012','中国电信 APP 签到金豆 + 充值折扣','话费充值','cash',0,'电信 APP 签到攒金豆可抽话费，充值享专属折扣，每月3号充值 95 折。','中国电信 APP（官方）','长期','verified',70,'["电信号码"]','["金豆玩法细则随时变"]','#','充值折扣','中国电信 APP → 签到/充值','approved','2026-10-22T00:00:00.000Z'),
('act-013','支付宝会员 积分兑话费红包（269积分兑1元）','话费充值','cash',0,'支付宝会员页搜「话费」，可用积分兑话费红包，电信 APP 充 1 元时支付宝抵扣。','支付宝（官方）','以会员页为准','verified',68,'["支付宝会员积分"]','["额度小"]','#','积分兑话费','支付宝 → 会员 → 搜话费','approved','2026-10-22T00:00:00.000Z'),
('act-014','微信 手机充值 不定时发2元话费券','话费充值','cash',0,'微信官方充值入口不定时发 2 元话费券（领后5天有效），常规面值建议与运营商 APP 比价。','微信/腾讯手机充值（官方）','不定期','verified',66,'["券不定期发放"]','["面值小、非必发"]','#','2元券','微信 → 我 → 服务 → 手机充值','approved','2026-10-22T00:00:00.000Z'),
